mapper.select:
select a.id, a.name, a.supplier_type, a.owner_user, a.status, a.mobile, a.email, a.detail_address, a.pay_type,
a.remark,
e.user_name as creator,
a.create_time, c.user_name as updater, a.update_time, a.deleted from crm_supplier a
left join sys_user c on a.updater=c.user_id
left join sys_user e on a.creator=e.user_id

    a.deleted = 0
     and a.name like concat('%', #{name}, '%')
     and a.supplier_type = #{supplierType}
     and a.owner_user = #{ownerUser}
     and a.status = #{status}
     and a.mobile = #{mobile}
     and a.email = #{email}
     and a.detail_address = #{detailAddress}
     and a.pay_type = #{payType}
     and a.creator = #{creator}
     and a.updater = #{updater}

mapper.update:
update crm_supplier
name = #{name}, supplier_type = #{supplierType}, owner_user = #{ownerUser}, status = #{status}, mobile = #{mobile}, email = #{email}, detail_address = #{detailAddress}, pay_type = #{payType}, remark = #{remark}, creator = #{creator}, create_time = #{createTime}, updater = #{updater}, update_time = #{updateTime}, deleted = #{deleted},
where id = #{id}
